// Settings -> object (client concierge bot, AI-guarded defaults).
// The Telegram bot secret is no longer read from Settings at all: transport runs entirely through n8n Credentials.
const rows = $input.all().map(i => i.json);
const settings = {};
for (const r of rows) {
  const key = (r.key ?? r.Key ?? '').toString().trim();
  if (!key) continue;
  settings[key] = (r.value ?? r.Value ?? '').toString().trim();
}
function bool(v, def){ if (v === undefined || v === '') return def; return String(v).toLowerCase() === 'true' || v === '1'; }
function num(v, def){ const n = Number(v); return Number.isFinite(n) ? n : def; }
const cfg = {
  owner_chat_id: settings.owner_chat_id || '<REDACTED_CHAT_ID>',
  timezone: settings.timezone || 'Europe/Chisinau',
  lead_intake_webhook_url: settings.lead_intake_webhook_url || 'https://ghennadi.app.n8n.cloud/webhook/finmentor-lead-intake',
  website_url: settings.website_url || 'https://finmentor.md',
  default_language: (settings.default_language || 'ru').toLowerCase(),
  bot_enabled: bool(settings.bot_enabled, true),
  client_ai_enabled: bool(settings.client_ai_enabled, false),
  client_ai_model: settings.client_ai_model || 'PASTE_AI_MODEL_PLACEHOLDER_HERE',
  client_ai_temperature: num(settings.client_ai_temperature, 0.2)
};
return [{ json: { settings: cfg } }];

// Parse Telegram Update (client bot). Trigger отдаёт update на верхнем уровне (или в .body).
const u = $('Telegram Client Trigger').first().json;
const update = u.body || u;
const cb = update.callback_query || null;
const msg = update.message || update.edited_message || null;

let chat_id='', user_id='', username='', first_name='', last_name='', language='', message_text='', callback_data='', callback_query_id='';
if (cb) {
  chat_id = String(cb.message && cb.message.chat ? cb.message.chat.id : '');
  user_id = String(cb.from ? cb.from.id : '');
  username = (cb.from && cb.from.username) || '';
  first_name = (cb.from && cb.from.first_name) || '';
  last_name = (cb.from && cb.from.last_name) || '';
  language = (cb.from && cb.from.language_code) || '';
  callback_data = cb.data || '';
  callback_query_id = cb.id || '';
} else if (msg) {
  chat_id = String(msg.chat ? msg.chat.id : '');
  user_id = String(msg.from ? msg.from.id : '');
  username = (msg.from && msg.from.username) || '';
  first_name = (msg.from && msg.from.first_name) || '';
  last_name = (msg.from && msg.from.last_name) || '';
  language = (msg.from && msg.from.language_code) || '';
  message_text = msg.text || '';
}
if (!chat_id) return [];  // служебный апдейт без чата — игнор
return [{ json: {
  chat_id, user_id, username, first_name, last_name, language,
  message_text, callback_data, callback_query_id,
  is_callback: !!cb,
  raw_update: JSON.stringify(update).slice(0, 4000)
}}];

// Session lookup moved out of the Google Sheets node.
// The node-level filtersUI triggered a false Retry On Fail: the read succeeded in ~440 ms but n8n still
// waited two 2000 ms back-offs, costing ~5.3 s on every client message. The read now returns all rows
// over an explicit A:AV range and the match happens here, in memory.
// CONTRACT: always returns EXACTLY ONE item, so no downstream node ever sees the full array.
// The target chat id comes ONLY from the parsed Telegram context, never from $json (which here is a sheet row).
const p = $('Parse Telegram Update').first().json;
const target = String(p.chat_id == null ? '' : p.chat_id);
const rows = $input.all().map(i => i.json).filter(r => r && r.chat_id !== undefined && String(r.chat_id).trim() !== '');
let matched = null;
for (const r of rows) { if (String(r.chat_id) === target) { matched = r; break; } }
if (matched) return [{ json: matched }];
// No row for this chat yet: hand the gateway a canonical empty session for THIS user only.
return [{ json: {
  row_number: 0,
  session_id: '',
  chat_id: target,
  user_id: String(p.user_id || ''),
  username: p.username || '',
  first_name: p.first_name || '',
  last_name: p.last_name || '',
  language: p.language || 'ru',
  state: '',
  created_at: '',
  updated_at: '',
  last_message_at: '',
  entry_source: '',
  selected_service: '',
  business_model: '',
  turnover_range: '',
  main_pain: '',
  urgency: '',
  has_cfo: '',
  documents_status: '',
  contact_phone: '',
  contact_email: '',
  contact_name: '',
  company: '',
  free_text_request: '',
  consent: '',
  lead_id: '',
  lead_sent_at: '',
  status: '',
  notes: '',
  raw_json: '',
  cycle_id: '',
  consent_cycle_id: '',
  consent_at: '',
  lead_cycle_id: '',
  lead_intake_ok: '',
  previous_lead_id: '',
  submission_key: ''
} }];

// CYCLE SEMANTICS GATE (P0 fix for stale consent).
// Every consumer that reads $('Get Bot Session') now sees a CYCLE-VALID view of the session:
// consent and lead_id from a previous application cycle are invalidated before the state machine ever sees them.
// A new cycle is created ONLY on an explicit reset: /start, or "Начать заново" (m|diag pressed on a session that
// already carries a consent decision, a lead, or an ended session). Plain navigation (/menu, n|menu) never changes it.
// An unfinished diagnostic cycle is never reset by m|diag, because there the same callback means "continue".
const p = $('Parse Telegram Update').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && String(r.chat_id == null ? '' : r.chat_id).trim() !== '');
const s = Object.assign({}, rows.length ? rows[0] : {});
const now = new Date().toISOString();
const text = String(p.message_text || '').trim().toLowerCase();
const cb = String(p.callback_data || '').trim();
const str = v => String(v == null ? '' : v).trim();
// ============ B.2.1-C P7.2 — ISSUANCE INPUTS, CAPTURED BEFORE THIS GATE MUTATES s ============
const persistedSubmissionKey = str(s.submission_key);
const persistedCycleIdAtEntry = str(s.cycle_id);

const isStart = text === '/start';
// "Завершённый" цикл: есть решение по согласию, есть лид, либо сессия явно завершена кнопкой "Завершить".
const carriesFinishedCycle = str(s.consent) !== '' || str(s.lead_id) !== '' || str(s.status).toLowerCase() === 'ended';
const isRestart = cb === 'm|diag' && carriesFinishedCycle;
const hasNoCycle = str(s.cycle_id) === '';

let cycleId = str(s.cycle_id);
let reset = '';
if (isStart) reset = 'start';
else if (isRestart) reset = 'restart';
else if (hasNoCycle) reset = 'bootstrap';
if (reset) cycleId = 'C-' + str(p.chat_id) + '-' + Date.now();

function archiveLead() {
  const old = str(s.lead_id);
  if (old) {
    const prev = str(s.previous_lead_id).split(';').map(x => x.trim()).filter(Boolean);
    if (!prev.includes(old)) prev.push(old);
    s.previous_lead_id = prev.join('; ').slice(0, 500);
  }
  s.lead_id = ''; s.lead_cycle_id = ''; s.lead_sent_at = ''; s.lead_intake_ok = '';
}

if (reset === 'start' || reset === 'restart') {
  // Explicit reset: a genuinely new application cycle.
  s.consent = ''; s.consent_cycle_id = ''; s.consent_at = '';
  archiveLead();
  s.selected_service = ''; s.business_model = ''; s.turnover_range = ''; s.main_pain = '';
  s.urgency = ''; s.has_cfo = ''; s.documents_status = ''; s.free_text_request = '';
  s.raw_json = ''; s.status = 'active'; s.state = 'MENU'; s.notes = '';
  // Identity and contact convenience fields are deliberately kept; on their own they cannot submit anything,
  // because consent is now empty and lead_ready requires a current-cycle consent.
}

s.cycle_id = cycleId;

// Independent of any reset: never let a consent or a lead from another cycle count for this one.
if (str(s.consent) !== '' && str(s.consent_cycle_id) !== cycleId) { s.consent = ''; s.consent_cycle_id = ''; s.consent_at = ''; }
if (str(s.lead_id) !== '' && str(s.lead_cycle_id) !== cycleId) { archiveLead(); }

s.cycle_reset = reset;

// ================ B.2.1-C P7.2 — SUBMISSION KEY ISSUANCE (ISSUANCE_ORDER step 1) ================
//
// The deployed form of decideIssuance() in n8n/src/concierge-issuer/mint-submission-key.js.
// The module is the GATED statement of this logic; qa/concierge-issuer-candidate.test.mjs
// drives both against one table of cases, so the two cannot drift apart silently.
//
// THE PRIMITIVE. require('crypto').randomBytes is the ONLY entropy source that answers in this
// sandbox: execution 3651 measured "typeof crypto === undefined" on this tenant. Writing the
// modern reflex (crypto.getRandomValues) or the specification's literal (crypto.randomBytes)
// here is not a degraded feature — it is a ReferenceError inside the node that every Telegram
// update passes through, i.e. a bot that stops answering /start for every user.
//
// THE FAILURE POSTURE. The mint is wrapped, and that wrapper is load-bearing. This node runs
// BEFORE the reply is composed, so an exception here costs the user their message. A mint that
// throws degrades to MINT_FAILED: the turn still answers, and it is the GRAPH that refuses to
// persist the new cycle. planIssuance() is explicit about why that refusal is the safe half — a
// half-advanced authority row (new cycle_id, no submission_key) makes every submit
// PRE_ACTIVATION_BLOCKED, locking the user out of a cycle that looks current.
//
// NEVER_BACKFILL. A cycle that exists without a key is NEVER given one retroactively. A legacy
// cycle may already have submitted — lead_id set, CRM row written — and a fresh READY receipt is
// positive evidence to the gateway that it has NOT, releasing a second attempt for a lead that
// is already in the pipeline. Cost of refusing: one restart. Cost of backfilling: a duplicate
// lead.
//
// The four annotations below are __-prefixed on purpose. They are decision metadata, not sheet
// columns, and F16 proved that a stray property reaching Save Bot Session does not vanish — it
// permanently widens Bot_Sessions. The three row builders emit their declared COLS only, and the
// prefix makes it visible at a glance that these were never candidates for that list.
const SUBMISSION_KEY_RE = /^sub_[0-9a-f]{32}$/;
function mintSubmissionKey() {
  const buf = require('crypto').randomBytes(16);
  if (!buf || typeof buf.length !== 'number' || buf.length !== 16) { throw new Error('randomBytes did not return 16 bytes'); }
  let hex = '';
  for (let i = 0; i < 16; i++) {
    const b = buf[i];
    if (typeof b !== 'number' || !isFinite(b) || b < 0 || b > 255 || (b | 0) !== b) { throw new Error('randomBytes returned a non-byte at index ' + i); }
    hex += (b < 16 ? '0' : '') + b.toString(16);
  }
  const k = 'sub_' + hex;
  if (!SUBMISSION_KEY_RE.test(k)) { throw new Error('minted key failed the format rule'); }
  return k;
}

let keyAction = '';
let keyReason = '';
let keyPreallocate = false;
if (reset !== '') {
  // A key is minted IF AND ONLY IF a new cycle is minted. Anything else desynchronises the pair
  // Bot_Sessions carries, and the gateway's SUBMISSION_KEY_DRIFT check exists precisely because
  // that pair must move together or not at all.
  try {
    s.submission_key = mintSubmissionKey();
    keyAction = 'MINT';
    keyReason = 'NEW_CYCLE_' + reset.toUpperCase();
    keyPreallocate = true;
  } catch (e) {
    s.submission_key = '';
    keyAction = 'MINT_FAILED';
    keyReason = 'MINT_THREW:' + String((e && e.message) || e).slice(0, 120);
  }
} else if (SUBMISSION_KEY_RE.test(persistedSubmissionKey)) {
  s.submission_key = persistedSubmissionKey;
  keyAction = 'CARRY';
  keyReason = 'CYCLE_UNCHANGED';
} else if (persistedSubmissionKey !== '') {
  // Carried UNCHANGED and never repaired. The gateway already refuses a malformed key
  // (SUBMISSION_KEY_INVALID, proven live); blanking it here would destroy the only evidence
  // that the row is corrupt while producing the identical refusal. The issuer reports; it does
  // not launder.
  s.submission_key = persistedSubmissionKey;
  keyAction = 'CARRY_MALFORMED';
  keyReason = 'KEY_MALFORMED_NOT_REPAIRED';
} else {
  s.submission_key = '';
  keyAction = 'LEGACY_NO_KEY';
  keyReason = persistedCycleIdAtEntry !== '' ? 'LEGACY_CYCLE_NOT_BACKFILLED' : 'NO_CYCLE_NO_KEY';
}
s.__submission_key_action = keyAction;
s.__submission_key_reason = keyReason;
s.__submission_key_preallocate = keyPreallocate;
s.__submission_key_fault = keyAction === 'MINT_FAILED';
return [{ json: s }];

// Build Bot Response - FINMENTOR Client Concierge final state-machine.
// State-first rules: when a concrete field is expected, never run intent classification first.
function safeText(value, max = 3800) {
  let text = String(value ?? "")
    .replace(/\r/g, "")
    .replace(/[<>]/g, "")
    .replace(/[_*\[\]()`~>#=|{}]/g, " ")
    .replace(/[ \t]+\n/g, "\n")
    .replace(/\n{4,}/g, "\n\n\n")
    .replace(/[ \t]{2,}/g, " ")
    .trim();
  if (!text) text = "Понял. Вернёмся в главное меню, где можно выбрать диагностику, встречу или свободно описать запрос.";
  if (text.length > max) text = text.slice(0, max).trim() + "...";
  return text;
}

function bool(value, fallback = false) {
  if (value === undefined || value === null || value === "") return fallback;
  return String(value).toLowerCase() === "true" || String(value) === "1";
}

function norm(value) {
  return String(value ?? "").toLowerCase().replace(/ё/g, "е").trim();
}

function empty(value) {
  return String(value ?? "").trim() === "";
}

function containsAny(text, patterns) {
  const s = norm(text);
  return patterns.some((pattern) => pattern.test(s));
}

function isNoCompanyText(value) {
  return containsAny(value, [
    /не хочу.*(компан|указывать)/,
    /конфиденциально/,
    /пока не скажу/,
    /позже/,
    /без компании/,
  ]);
}

function isNoContactText(value) {
  return containsAny(value, [
    /не хочу.*(контакт|оставлять)/,
    /без контакта/,
    /пока нет/,
    /позже/,
    /не оставлять/,
  ]);
}

function isNoTurnoverText(value) {
  return containsAny(value, [
    /не хочу.*оборот/,
    /не указывать.*оборот/,
    /без оборота/,
    /оборот.*позже/,
    /конфиденциально/,
  ]);
}

function isConsentYes(value) {
  return containsAny(value, [/^да$/, /соглас/, /подтвержд/, /можно/, /передать/, /\byes\b/, /\bok\b/]);
}

function isConsentNo(value) {
  return containsAny(value, [/^нет$/, /не соглас/, /не надо/, /не передав/, /пока не/, /\bno\b/]);
}

function isPersonIntro(value) {
  const text = safeText(value, 200);
  const s = norm(text);
  if (!s || text.length > 120) return false;
  if (/[?？]/.test(text) || /^(как|что|сколько|когда|где|почему|зачем)\b/.test(s)) return false;
  if (containsAny(s, [/нужен/, /нужна/, /нужно/, /требуется/, /ищу/, /хочу/, /проблем/, /нет/, /стоимост/, /цена/, /услуг/, /помогите/, /консультац/])) return false;
  const words = s
    .replace(/[.,;:!?()[\]{}"«»—–-]/g, " ")
    .split(/\s+/)
    .filter(Boolean);
  if (words.length < 1 || words.length > 5) return false;
  const roleHit = containsAny(s, [
    /собственник/,
    /финансовый директор/,
    /директор/,
    /\bceo\b/,
    /\bcfo\b/,
    /руководитель/,
    /бухгалтер/,
    /управляющ/,
    /основатель/,
  ]);
  const hasLetters = /[a-zа-я]/i.test(text);
  return hasLetters && roleHit;
}

const cfg = (function () {
  try {
    return $("Settings to Object").first().json.settings || {};
  } catch (e) {
    return {};
  }
})();

const site = cfg.website_url || "https://finmentor.md";
const lang = (cfg.default_language || "ru").toLowerCase();
const clientAiEnabled = bool(cfg.client_ai_enabled, false);

const p = $("Parse Telegram Update").first().json;
const chat_id = p.chat_id;
const isCb = !!p.is_callback;
const data = String(p.callback_data || "").trim();
const text = String(p.message_text || "").trim();

const now = new Date().toISOString();

const ALLOWED_STATES = [
  "START",
  "MENU",
  "SERVICE_SELECTED",
  "BUSINESS_MODEL_SELECTED",
  "TURNOVER_SELECTED",
  "MAIN_PAIN_SELECTED",
  "URGENCY_SELECTED",
  "HAS_CFO_SELECTED",
  "DOCUMENTS_SELECTED",
  "CONTACT_NAME_REQUESTED",
  "COMPANY_REQUESTED",
  "CONTACT_REQUESTED",
  "CONSENT_REQUESTED",
  "LEAD_SENT",
  "CONSENT_DECLINED",
  "ENDED",
];

const SERVICE = {
  xray: "Financial X-Ray / диагностика",
  cashflow: "Cash Flow / деньги",
  receivables: "Контроль дебиторской задолженности",
  inventory: "Запасы / оборотный капитал",
  pnl: "P&L / маржинальность",
  bi: "BI / отчётность",
  automation: "Автоматизация",
  cfo: "CFO-сопровождение",
  meeting: "Discovery Call",
  free_text: "Free Text Request",
};

const BUSINESS_MODEL = {
  trade: "Торговля",
  manuf: "Производство",
  construction: "Строительство / Real Estate",
  horeca: "HoReCa",
  services: "Услуги / логистика",
  ecommerce: "E-commerce",
  other: "Другое / смешанная модель",
};

const TURNOVER = {
  lt100: "до 100k EUR/год",
  "100_500": "100k-500k EUR/год",
  "500_2m": "500k-2M EUR/год",
  "2m_10m": "2M-10M EUR/год",
  "10m_plus": "10M+ EUR/год",
  skip: "Не указано",
};

const PAIN = {
  no_money: "Деньги есть в продажах, но не хватает ликвидности",
  no_cashflow: "Нет понятного Cash Flow",
  receivables: "Растёт дебиторская задолженность / деньги зависают у клиентов",
  margin: "Непонятна маржинальность",
  no_profit: "Собственник не видит реальную прибыль",
  manual: "Отчётность собирается вручную",
  no_cfo: "Нет финансового директора / управленческого контроля",
  automation: "Нужна автоматизация финансовой отчётности",
};

const URGENCY = {
  urgent: "Срочно, в течение недели",
  month: "В течение месяца",
  quarter: "В ближайший квартал",
  exploring: "Пока изучаю варианты",
};

const CFO = {
  yes: "Да, есть CFO",
  book_no_control: "Есть бухгалтерия, но нет управленческого контроля",
  none: "Нет отдельного финансового блока",
  unsure: "Сложно оценить",
};

const DOC = {
  cashflow: "Cash Flow / платежи",
  pnl: "P&L / прибыль и убытки",
  receivables: "Дебиторская и кредиторская задолженность",
  sales: "Продажи и маржа",
  excel: "Excel-таблицы",
  nothing: "Пока ничего не подготовлено",
};

function hasContact(s) {
  return !!(s.contact_phone || s.contact_email);
}

function inferState(s) {
  if (!empty(s.contact_name) && empty(s.company)) return "COMPANY_REQUESTED";
  if (!empty(s.contact_name) && !empty(s.company) && !hasContact(s)) return "CONTACT_REQUESTED";
  if (!empty(s.contact_name) && !empty(s.company) && hasContact(s) && empty(s.consent)) return "CONSENT_REQUESTED";
  return s.state || "MENU";
}

function baseSession(seed = {}) {
  return {
    session_id: seed.session_id || "S-" + chat_id + "-" + Date.now(),
    chat_id,
    user_id: seed.user_id || p.user_id || "",
    username: seed.username || p.username || "",
    first_name: seed.first_name || p.first_name || "",
    last_name: seed.last_name || p.last_name || "",
    language: seed.language || p.language || lang,
    state: seed.state || "START",
    created_at: seed.created_at || now,
    updated_at: now,
    last_message_at: now,
    entry_source: seed.entry_source || "telegram_client_concierge",
    selected_service: seed.selected_service || "",
    business_model: seed.business_model || "",
    turnover_range: seed.turnover_range || "",
    main_pain: seed.main_pain || "",
    urgency: seed.urgency || "",
    has_cfo: seed.has_cfo || "",
    documents_status: seed.documents_status || "",
    contact_phone: seed.contact_phone || "",
    contact_email: seed.contact_email || "",
    contact_name: seed.contact_name || "",
    company: seed.company || "",
    free_text_request: seed.free_text_request || "",
    consent: seed.consent || "",
    lead_id: seed.lead_id || "",
    lead_sent_at: seed.lead_sent_at || "",
    status: seed.status || "active",
    notes: seed.notes || "",
    raw_json: seed.raw_json || "",
  };
}

function normalizeSessionRows(rows) {
  const sameChat = rows.filter((r) => String(r.chat_id || "") === String(chat_id));
  const normalized = sameChat.map((r) => baseSession(r));
  normalized.sort((a, b) => new Date(b.updated_at || 0) - new Date(a.updated_at || 0));
  const good = normalized.find((r) => !empty(r.session_id) && !empty(r.state));
  const partial = normalized.find((r) => !empty(r.session_id) || !empty(r.contact_name) || !empty(r.company) || hasContact(r));
  const chosen = good || partial || null;
  if (!chosen) return { session: baseSession(), recovered: false };
  let recovered = false;
  if (!ALLOWED_STATES.includes(chosen.state)) {
    chosen.state = "MENU";
    recovered = true;
  }
  const inferred = inferState(chosen);
  if ((empty(chosen.state) || ["START", "MENU", "SERVICE_SELECTED"].includes(chosen.state)) && inferred !== chosen.state) {
    chosen.state = inferred;
    recovered = true;
  }
  if (empty(chosen.session_id)) {
    chosen.session_id = "S-" + chat_id + "-" + Date.now();
    recovered = true;
  }
  return { session: chosen, recovered };
}

let rawSessions = [];
try {
  rawSessions = $("Get Bot Session").all().map((i) => i.json).filter((r) => r && r.chat_id);
} catch (e) {
  rawSessions = [];
}

let { session, recovered: stateRecovered } = normalizeSessionRows(rawSessions);
session.updated_at = now;
session.last_message_at = now;
if (p.username) session.username = p.username;
if (p.first_name) session.first_name = p.first_name;
if (p.last_name) session.last_name = p.last_name;
if (p.language) session.language = p.language;

const stateBefore = session.state || "START";

function appendNote(flag) {
  const parts = String(session.notes || "").split(";").map((x) => x.trim()).filter(Boolean);
  if (!parts.includes(flag)) parts.push(flag);
  session.notes = parts.join("; ").slice(0, 500);
}

function removeNotes(flags) {
  const remove = new Set(flags);
  const parts = String(session.notes || "").split(";").map((x) => x.trim()).filter(Boolean);
  session.notes = parts.filter((x) => !remove.has(x)).join("; ").slice(0, 500);
}

