function classifyIntentFallback(value) {
  const s = norm(value);
  if (!s) return { intent: "unknown", selected_service: "", detail: "unknown" };
  if (isPersonIntro(value)) return { intent: "person_intro", selected_service: "", detail: "person_intro_detected" };
  if (containsAny(s, [/здравствуй/, /добрый день/, /доброе утро/, /добрый вечер/, /\bhi\b/, /\bhello\b/, /привет/])) {
    return { intent: "greeting", selected_service: "", detail: "menu_opened" };
  }
  if (containsAny(s, [/не хочу.*анкет/, /не хочу.*отвеч/, /без анкет/, /без вопросов/, /давайте без/, /просто свяж/, /позвоните/, /оставлю номер/, /сразу встреч/, /без диагностики/])) {
    return { intent: "skip_questionnaire", selected_service: SERVICE.free_text, detail: "questionnaire_skipped" };
  }
  if (containsAny(s, [/сколько стоит/, /цена/, /прайс/, /тариф/, /стоимость/, /сколько берете/])) {
    return { intent: "ask_price", selected_service: "", detail: "price_question" };
  }
  if (containsAny(s, [/услуг/, /что вы делаете/, /чем занимаетесь/, /что предлагаете/, /finmentor/])) {
    return { intent: "ask_services", selected_service: "", detail: "services_requested" };
  }
  if (containsAny(s, [/встреч/, /созвон/, /связаться/, /перезвон/, /позвон/, /discovery/, /консультац/])) {
    return { intent: "request_meeting", selected_service: SERVICE.meeting, detail: "meeting_requested" };
  }
  if (isNoContactText(s)) return { intent: "no_contact", selected_service: "", detail: "no_contact" };
  if (isNoCompanyText(s)) return { intent: "no_company", selected_service: "", detail: "no_company" };
  if (isNoTurnoverText(s)) return { intent: "no_turnover", selected_service: "", detail: "no_turnover" };
  if (containsAny(s, [
    /нуж.*cfo/,
    /нуж.*финансов.*директор/,
    /ищу.*финансов.*директор/,
    /хочу.*cfo[-\s]?сопровожд/,
    /нет.*финансов.*директор/,
    /нуж.*финансов.*контрол/,
    /нуж.*финансов.*блок/,
    /нуж.*управлен.*финансов.*функц/,
    /требуется.*финансов.*директор/,
    /требуется.*управлен.*финансов.*функц/,
  ])) {
    return { intent: "cfo_support", selected_service: SERVICE.cfo, detail: "free_text_intent_detected" };
  }
  if (containsAny(s, [/cash\s*flow/, /кэш/, /денег/, /деньги/, /платеж/, /ликвидн/])) {
    return { intent: "cashflow", selected_service: SERVICE.cashflow, detail: "free_text_intent_detected" };
  }
  if (containsAny(s, [/дебитор/, /долг/, /задолж/])) return { intent: "receivables", selected_service: SERVICE.receivables, detail: "free_text_intent_detected" };
  if (containsAny(s, [/запас/, /склад/, /товарн/])) return { intent: "inventory", selected_service: SERVICE.inventory, detail: "free_text_intent_detected" };
  if (containsAny(s, [/p&l/, /pnl/, /марж/, /прибыл/, /убыт/])) return { intent: "pnl_margin", selected_service: SERVICE.pnl, detail: "free_text_intent_detected" };
  if (containsAny(s, [/power\s*bi/, /dashboard/, /дашборд/, /отчетн/, /bi\b/])) return { intent: "power_bi", selected_service: SERVICE.bi, detail: "free_text_intent_detected" };
  if (containsAny(s, [/автоматизац/, /\bn8n\b/, /\bmake\b/, /интеграц/])) return { intent: "automation", selected_service: SERVICE.automation, detail: "free_text_intent_detected" };
  return { intent: "write_free_request", selected_service: SERVICE.free_text, detail: "free_text_intent_detected" };
}

function fallbackFreeTextResponse(value, detailOverride = "") {
  const intent = classifyIntentFallback(value);
  if (intent.intent === "person_intro" && empty(session.contact_name)) {
    session.contact_name = safeText(value, 120);
    return askStep("company");
  }
  if (intent.selected_service && empty(session.selected_service)) session.selected_service = intent.selected_service;
  if (intent.selected_service && session.selected_service === SERVICE.free_text) session.selected_service = intent.selected_service;
  if (value) session.free_text_request = safeText(value, 500);
  if (!session.main_pain && !["greeting", "ask_price", "ask_services", "person_intro"].includes(intent.intent)) session.main_pain = safeText(value, 300);
  if (intent.intent === "greeting") return screenMenu();
  if (intent.intent === "skip_questionnaire") return screenSkipQuestionnaire();
  if (intent.intent === "ask_price") return screenPrice();
  if (intent.intent === "ask_services") return screenServices();
  if (intent.intent === "request_meeting") {
    session.selected_service = SERVICE.meeting;
    return nextContactStep("Понял. Чтобы встреча была предметной, уточним только минимум.", "meeting_requested");
  }
  if (intent.intent === "no_contact") return contactSkippedScreen();
  const serviceLine = intent.selected_service ? "Похоже, запрос связан с направлением: " + intent.selected_service + "." : "";
  return {
    state: "SERVICE_SELECTED",
    text:
      "Спасибо, понял запрос. " +
      serviceLine +
      "\n\nЧтобы эксперт FINMENTOR вернулся к вам предметно, можно либо пройти короткую диагностику, либо оставить контакт и одну фразу по задаче.",
    markup: kb([
      [{ text: "🚀 Продолжить диагностику", callback_data: "m|diag" }],
      [{ text: "✅ Оставить контакт", callback_data: "m|meeting_contact" }],
      [{ text: "💼 Услуги FINMENTOR", callback_data: "m|services" }],
      MENU_ROW,
    ]),
    detail: detailOverride || intent.detail,
  };
}

function extractContact(value) {
  const v = value.trim();
  const email = v.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
  if (email) {
    session.contact_email = email[0].slice(0, 160);
    return true;
  }
  const phone = v.match(/(\+?\d[\d\s().-]{6,}\d)/);
  if (phone) {
    session.contact_phone = phone[0].replace(/\s+/g, " ").slice(0, 80);
    return true;
  }
  if (v.startsWith("@") && v.length > 1) {
    session.contact_phone = v.slice(0, 80);
    return true;
  }
  return false;
}

function useTelegramContact() {
  const username = session.username || p.username || "";
  session.contact_phone = username ? "Telegram: @" + String(username).replace(/^@/, "") : "Telegram chat_id: " + String(chat_id);
  appendNote("telegram_contact_used");
  return true;
