  return hasName && hasContactData && hasNeed && session.consent === "yes";
}

function missingMinimumScreen() {
  if (empty(session.contact_name) && empty(session.username) && empty(session.first_name)) return askStep("contact_name", "Чтобы передать запрос эксперту, нужно понять, как к вам обращаться.");
  if (!hasContact(session)) return askStep("contact", "Чтобы передать запрос эксперту, нужен удобный контакт для ответа.");
  if (empty(session.selected_service) && empty(session.free_text_request) && empty(session.main_pain)) return askFreeText();
  return askStep("contact_name");
}

function nextContactStep(prefixText = "", detail = "contact_requested") {
  appendNote("contact_flow_active");
  if (empty(session.selected_service)) session.selected_service = session.free_text_request || session.main_pain ? SERVICE.free_text : SERVICE.meeting;
  if (empty(session.contact_name)) {
    const out = askStep("contact_name", prefixText);
    out.detail = detail;
    return out;
  }
  if (empty(session.company)) return askStep("company", prefixText);
  if (!hasContact(session)) return askStep("contact", prefixText);
  if (session.consent !== "yes") return askConsent(prefixText);
  if (hasMinimumLeadData()) return { state: "LEAD_SENT", text: "Готовлю запрос для эксперта FINMENTOR.", markup: kb([]), detail: "lead_prepared", leadReady: true };
  return missingMinimumScreen();
}

function prepareLeadPayload() {
  const leadId = session.lead_id || "TG-" + chat_id + "-" + Date.now();
  session.lead_id = leadId;
  session.status = "lead_pending";
  const telegram = session.username ? "@" + session.username : String(chat_id);
  const selectedService = session.selected_service || SERVICE.free_text;
  const mainPain = session.main_pain || session.free_text_request || selectedService;
  const businessModel = session.business_model || "Не указано";
  const payload = {
    lead_id: leadId,
    tool: "telegram_client_concierge",
    created_at: now,
    client: {
      name: session.contact_name || session.first_name || session.username || "",
      company: session.company || "Не указано",
      email: session.contact_email || "",
      phone_or_messenger: session.contact_phone || "",
      telegram,
      language: session.language || lang,
    },
    answers: {
      selected_service: selectedService,
      main_pain: mainPain,
      revenue_range: session.turnover_range || "",
      business_model: businessModel,
      has_cfo: session.has_cfo || "",
      documents_status: session.documents_status || "",
    },
    diagnostic: {
      score: "",
      traffic_light: "",
      urgency: session.urgency || "",
      main_pain: mainPain,
      business_model: businessModel,
    },
    meta: {
      consent: true,
      page_url: "telegram_client_bot",
      utm_source: "telegram",
      utm_medium: "client_bot",
      utm_campaign: "direct_telegram_concierge",
      ai_guarded: clientAiEnabled,
    },
    intake: {
      commercial_intent: { work_interest: [selectedService] },
      business_pain: { selected_problems: [mainPain], urgency: session.urgency || "" },
      documents_available: { selected_documents: [session.documents_status || ""] },
    },
  };
  session.raw_json = JSON.stringify(payload).slice(0, 4000);
  return payload;
}

let out = { state: session.state || "MENU", text: "", markup: menuKeyboard(), detail: stateRecovered ? "state_recovered" : "unknown" };
let leadReady = false;
let leadPayload = null;
let eventType = isCb ? "callback" : "message";

if (String(cfg.bot_enabled).toLowerCase() === "false") {
  out = { state: "MENU", text: "Сейчас Telegram Concierge временно недоступен. Вы можете оставить запрос на сайте FINMENTOR или вернуться позже.", markup: kb([[SITE_BTN], MENU_ROW]), detail: "bot_disabled" };
} else if (isCb) {
  const [prefix, ...rest] = data.split("|");
  const arg = rest.join("|");
  if (prefix === "n" && arg === "menu") out = screenMenu();
  else if (prefix === "n" && arg === "end") out = endScreen();
  else if (prefix === "m" && arg === "diag") out = askStep("service");
  else if (prefix === "m" && arg === "services") out = screenServices();
  else if (prefix === "m" && arg === "price") out = screenPrice();
  else if (prefix === "m" && arg === "free_text") out = askFreeText();
  else if (prefix === "m" && arg === "skip_questionnaire") out = screenSkipQuestionnaire();
  else if (prefix === "m" && (arg === "meeting_contact" || arg === "meeting")) {
    if (empty(session.selected_service)) session.selected_service = SERVICE.meeting;
    out = nextContactStep("Понял. Чтобы встреча была предметной, уточним только минимум.", "meeting_requested");
  } else if (prefix === "m" && arg === "to_contact") {
    out = nextContactStep("Хорошо, перейдём к контакту, чтобы эксперт FINMENTOR вернулся предметно.", "shortcut_to_contact");
  } else if (prefix === "m" && arg === "xray") {
    out = {
      state: "MENU",
      text: "Financial X-Ray — это короткий управленческий разбор финансов бизнеса: cash flow, задолженность, маржа, запасы и отчётность. Первый результат — понятная карта проблем и следующий шаг.",
      markup: kb([[{ text: "🚀 Пройти короткую диагностику", callback_data: "m|diag" }], [{ text: "📅 Обсудить с экспертом", callback_data: "m|meeting_contact" }], MENU_ROW]),
      detail: "xray_requested",
    };
  } else if (prefix === "s") {
    session.selected_service = SERVICE[arg] || SERVICE.xray;
    out = askStep("business_model");
  } else if (prefix === "b") {
    session.business_model = BUSINESS_MODEL[arg] || BUSINESS_MODEL.other;
    out = askStep("turnover");
  } else if (prefix === "t") {
    session.turnover_range = TURNOVER[arg] || TURNOVER.skip;
    out = arg === "skip" ? askStep("main_pain", "Понимаю. Тогда пропустим оборот и продолжим без этой информации.") : askStep("main_pain");
  } else if (prefix === "p") {
    session.main_pain = PAIN[arg] || "";
    out = askStep("urgency");
  } else if (prefix === "u") {
    session.urgency = URGENCY[arg] || "";
    out = askStep("has_cfo");
  } else if (prefix === "c") {
    session.has_cfo = CFO[arg] || "";
    out = askStep("documents");
  } else if (prefix === "d") {
    session.documents_status = DOC[arg] || "";
    out = askStep("contact_name");
  } else if (prefix === "company" && arg === "skip") {
    session.company = "Не указано / confidential";
    out = askStep("contact", "Понимаю. Можно продолжить без названия компании.");
    out.detail = "no_company";
  } else if (prefix === "contact" && arg === "telegram") {
    useTelegramContact();
    out = askConsent();
    out.detail = "telegram_contact_used";
  } else if (prefix === "contact" && arg === "skip") {
    out = contactSkippedScreen();
  } else if (prefix === "consent" && arg === "yes") {
    session.consent = "yes";
    if (hasMinimumLeadData()) {
      leadReady = true;
      eventType = "lead_sent";
      out = { state: "LEAD_SENT", text: "Готовлю запрос для эксперта FINMENTOR.", markup: kb([]), detail: "lead_prepared" };
    } else out = missingMinimumScreen();
  } else if (prefix === "consent" && arg === "no") out = consentDeclinedScreen();
  else out = { state: "MENU", text: "Похоже, я не совсем понял контекст. Давайте вернёмся к удобному выбору: короткая диагностика, встреча или свободное описание запроса.", markup: menuKeyboard(), detail: "duplicate_callback_handled" };
} else if (text) {
  const lower = norm(text);
  if (lower === "/start" || lower === "/menu") out = screenMenu();
  else if (lower === "/end" || lower === "стоп" || lower === "завершить") out = endScreen();
  else if (stateBefore === "CONTACT_NAME_REQUESTED") {
    session.contact_name = safeText(text, 120);
    out = askStep("company");
    out.detail = "contact_name_captured";
  } else if (stateBefore === "COMPANY_REQUESTED") {
    if (isNoCompanyText(text)) {
      session.company = "Не указано / confidential";
      out = askStep("contact", "Понимаю. Можно продолжить без названия компании.");
      out.detail = "no_company";
    } else {
      session.company = safeText(text, 160);
      out = askStep("contact");
      out.detail = "company_captured";
    }
  } else if (stateBefore === "CONTACT_REQUESTED") {
    if (isNoContactText(text)) out = contactSkippedScreen();
    else if (extractContact(text)) {
      out = askConsent();
      out.detail = "contact_captured";
    } else {
      out = askStep("contact", "Кажется, здесь нет телефона, email или @username. Напишите, пожалуйста, любой удобный контакт — или можно пропустить.");
      out.detail = "contact_retry";
    }
  } else if (stateBefore === "CONSENT_REQUESTED") {
    if (isConsentYes(text)) {
      session.consent = "yes";
      if (hasMinimumLeadData()) {
        leadReady = true;
        eventType = "lead_sent";
        out = { state: "LEAD_SENT", text: "Готовлю запрос для эксперта FINMENTOR.", markup: kb([]), detail: "lead_prepared" };
      } else out = missingMinimumScreen();
    } else if (isConsentNo(text)) out = consentDeclinedScreen();
    else out = askConsent("Понял. Для передачи запроса эксперту нужно явное согласие.");
  } else if (
    String(session.notes || "").includes("contact_flow_active") &&
    empty(session.contact_name) &&
    isPersonIntro(text)
  ) {
    session.contact_name = safeText(text, 120);
    appendNote("state_recovered_contact_name");
    out = askStep("company");
    out.detail = "contact_name_captured_recovered";
  } else if (lower === "/services") out = screenServices();
  else if (lower === "/contact") out = nextContactStep("", "contact_requested");
  else if (stateBefore === "TURNOVER_SELECTED" && isNoTurnoverText(text)) {
    session.turnover_range = TURNOVER.skip;
    out = askStep("main_pain", "Понимаю. Тогда пропустим оборот и продолжим без этой информации.");
  } else if (stateBefore === "SERVICE_SELECTED" && String(session.notes || "").includes("awaiting_free_text_request")) {
    session.free_text_request = safeText(text, 500);
    session.main_pain = session.main_pain || session.free_text_request;
    const intent = classifyIntentFallback(text);
    if (intent.selected_service && session.selected_service === SERVICE.free_text) session.selected_service = intent.selected_service;
    appendNote("free_text_request_captured");
    out = askStep("contact_name", "Спасибо, понял запрос. Чтобы эксперт FINMENTOR смог вернуться к вам предметно, уточним контакт.");
    out.detail = "free_text_intent_detected";
  } else if (isPersonIntro(text) && empty(session.contact_name) && ["START", "MENU", "SERVICE_SELECTED"].includes(stateBefore)) {
    session.contact_name = safeText(text, 120);
    out = askStep("company");
    out.detail = stateRecovered ? "contact_name_captured_recovered" : "contact_name_captured";
  } else {
    out = fallbackFreeTextResponse(text, clientAiEnabled ? "ai_fallback_used" : "");
    if (clientAiEnabled) appendNote("ai_fallback_used");
  }
} else {
  out = screenMenu();
}

if (!ALLOWED_STATES.includes(out.state)) out.state = "MENU";
session.state = out.state;

if (out.leadReady) leadReady = true;

if (leadReady) {
  if (session.consent !== "yes" || !hasMinimumLeadData()) {
    leadReady = false;
    out = missingMinimumScreen();
    session.state = out.state;
  } else {
    if (empty(session.selected_service)) session.selected_service = session.free_text_request ? SERVICE.free_text : SERVICE.meeting;
    leadPayload = prepareLeadPayload();
  }
}

const replyText = safeText(out.text);
const tgBody = { chat_id, text: replyText, reply_markup: out.markup || menuKeyboard() };
const eventDetail = out.detail || (stateRecovered ? "state_recovered" : (leadReady ? "lead_prepared" : "message_processed"));

return [{
  json: {
    chat_id,
    reply_text: replyText,
    reply_markup: out.markup || menuKeyboard(),
    tg_body: tgBody,
    session,
    lead_ready: leadReady,
    lead_payload: leadPayload,
    ai_guarded: { enabled: clientAiEnabled, model: cfg.client_ai_model || "", used: false, fallback_used: false },
    debug: {
      state_before: stateBefore,
      state_after: session.state,
      detail: eventDetail,
      session_notes: session.notes || "",
    },
    event: {
      event_type: eventType,
      state_before: stateBefore,
      state_after: session.state,
      message_text: text,
      callback_data: data,
      detail: eventDetail,
    },
  },
}];

// Presentation contract for FINMENTOR Telegram Client Transport.
// The state machine already emits reply_markup.inline_keyboard, so the layout id is derived from the ACTUAL
// keyboard shape + per-position button type. Nothing inside the state machine is modified.
// Approved UX note: a [U],[C] keyboard (bot_disabled screen) is normalised to [C],[U] = L2_CU.
// An unknown signature is NEVER silently downgraded to L0_NONE: it is routed to the controlled recovery branch.
// L0_NONE is reserved for screens that genuinely have no keyboard by design (empty signature).
const b = $('Build Bot Response').first().json;
const p = $('Parse Telegram Update').first().json;
const body = b.tg_body || {};
let rows = (body.reply_markup && Array.isArray(body.reply_markup.inline_keyboard)) ? body.reply_markup.inline_keyboard : [];

function typeOf(btn) { if (btn && typeof btn.url === 'string' && btn.url.trim() !== '') return 'U'; return 'C'; }
function sig(rws) { return rws.map(r => (r || []).map(typeOf).join('')).join('|'); }

let signature = sig(rows);
if (signature === 'U|C') { rows = [rows[1], rows[0]]; signature = 'C|U'; }

const MAP = {
  '': 'L0_NONE',
  'C': 'L1_C',
  'C|C': 'L2_C',
  'C|U': 'L2_CU',
  'C|C|C': 'L3_C',
  'C|C|U': 'L3_CCU',
  'C|C|C|C': 'L4_CCCC',
  'C|C|U|C': 'L4_CCUC',
  'C|C|C|U|C': 'L5_CCCUC',
  'C|C|C|C|C|C': 'L6_C',
  'C|C|C|C|C|C|C': 'L7_C',
  'C|C|C|C|C|C|C|C': 'L8_C',
  'C|C|C|C|UC': 'LAYOUT_MENU',
  'CC|C|CC|CC|C': 'LAYOUT_BMODEL'
};

const layout = MAP[signature] || '';
const mapped = layout !== '';

const kbRows = rows.map(r => (r || []).map(btn => {
  const o = { text: String((btn && btn.text) || '') };
  if (typeOf(btn) === 'U') o.url = String(btn.url); else o.callback_data = String((btn && btn.callback_data) || '');
  return o;
}));

// Stable Telegram identity, not a random id: needed for duplicate protection and tracing.
const corr = p.is_callback ? ('cb:' + String(p.callback_query_id || '')) : ('msg:' + String(p.chat_id || '') + ':' + String(p.message_text || '').slice(0, 24));

return [{ json: {
  chat_id: String(body.chat_id || b.chat_id || ''),
  text: String(body.text || ''),
  keyboard_layout_id: layout,
  keyboard_data: { rows: kbRows },
  parse_mode: '',
  disable_preview: true,
  correlation_id: corr.slice(0, 100),
  layout_mapped: mapped,
  keyboard_signature: signature
} }];

// B.2.1-C P7.2 — the issuance gate.
//
// Reached only after IF Message Delivered confirmed ok === true. It does NOT re-decide: the
// cycle gate already made the decision, and a second decision site is a second thing to drift.
// What it does is re-prove the one precondition an INSERT must never run without — a
// well-formed key — and name the fault when there is one.
const g = $('Get Bot Session').first().json || {};
const p = $('Parse Telegram Update').first().json || {};
const t = $input.first().json || {};
const str = v => String(v == null ? '' : v).trim();

const key = str(g.submission_key);
const action = str(g.__submission_key_action);
const wellFormed = /^sub_[0-9a-f]{32}$/.test(key);
const wants = g.__submission_key_preallocate === true;

// Three independent faults rather than one boolean, so the Bot_Events row says which happened.
//
// NO_ISSUANCE_DECISION is a DRIFT GUARD and it fails closed on purpose. It can only fire if
// this node is running against a Get Bot Session that has no issuance block — i.e. one half of
// this candidate was reverted by hand. Every new cycle would then be persisted with no key,
// which is exactly the half-advanced authority row planIssuance() refuses. A loud stop beats a
// quiet stream of unsubmittable cycles.
let fault = '';
if (g.__submission_key_fault === true || action === 'MINT_FAILED') { fault = 'MINT_FAILED'; }
else if (action === '') { fault = 'NO_ISSUANCE_DECISION'; }
else if (wants && !wellFormed) { fault = 'MINT_UNUSABLE'; }

return [{ json: {
  __submission_key: key,
  __issuance_action: action,
  __issuance_reason: str(g.__submission_key_reason),
  __preallocate: fault === '' && wants,
  __fault: fault !== '',
  __fault_reason: fault,
  __chat_id: str(p.chat_id),
  __correlation_id: str(t.correlation_id)
} }];

// B.2.1-C P7.2 — ISSUANCE_ORDER steps 3-5, deployed form of verifyPreallocationReadback().
//
// WHAT IS AND IS NOT CONFIRMATION. P2 proved this Data Table has NO uniqueness constraint: two
// inserts of one key both succeed and neither errors. So an id in the insert output, an
// insertedCount, a 2xx and the absence of an exception are all reports about the CALL, and none
// of them is evidence about the STATE. Only state can justify advancing authority, so authority
// advances on an exact-key readback whose CARDINALITY and CONTENT are both checked, or not at
// all. There is no partial credit and no probably-fine branch.
//
// THE ZERO-ITEM DISCRIMINATOR. Receipt Readback carries alwaysOutputData, which is load-bearing:
// P4 proved a zero-match returns main[0] === [] and skips every downstream node, so without it
// the fail-closed branch could never run. The cost is that "no match" arrives as ONE EMPTY ITEM,
// and an empty item is not a row. It is discriminated by KEY COUNT — never by truthiness, which
// an empty object passes, and never by try/catch, which never fires.
const gate = $('Issuance Gate').first().json || {};
const key = gate.__submission_key;
const norm = v => String(v == null ? '' : v).trim();

let insert = {};
try { insert = $('Receipt Preallocate').first().json || {}; } catch (e) { insert = {}; }
const insertErrored = !!(insert.error || insert.errorMessage);

const raw = $input.all().map(i => i.json).filter(r => r && typeof r === 'object' && !Array.isArray(r));
const storeError = raw.some(r => r.error || r.errorMessage);
const rows = raw.filter(r => Object.keys(r).length > 0 && !r.error && !r.errorMessage);

function refuse(reason, extra) {
  return [{ json: Object.assign({
    __advance: false,
    __reason: reason,
    __verified_submission_key: '',
    __rows_seen: rows.length,
    __insert_errored: insertErrored
  }, extra || {}) }];
}

if (!/^sub_[0-9a-f]{32}$/.test(norm(key))) { return refuse('SUBMISSION_KEY_INVALID'); }
// "We could not look" and "it is there" must never collapse into one outcome.
if (storeError) { return refuse('READBACK_STORE_ERROR'); }

// RAW exact equality, deliberately not a trim. A trim is a REPAIR, and a MODEL B key is an
// opaque server-minted value: a stored "sub_...abc " is not the same key with a stray space, it
// is evidence that something wrote a value the minter never produced or that the store is
// mangling what it holds. Trimming it into a match is how a corrupted row reaches authority.
for (let i = 0; i < rows.length; i++) {
  const stored = rows[i].submission_key;
  if (typeof stored !== 'string' || stored !== key) { return refuse('READBACK_WRONG_KEY'); }
}
if (rows.length === 0) { return refuse('READBACK_ABSENT'); }
if (rows.length > 1) { return refuse('READBACK_DUPLICATE'); }

const row = rows[0];
if (norm(row.commit_state) !== 'READY') { return refuse('READBACK_WRONG_STATE'); }

// A pristine preallocation carries no settlement residue AND no classification residue. The
// classification fields matter as much as the settlement ones: classifyRows replays lead_mode,
// lead_priority and financial_zone on a COMMITTED read, so a READY row already carrying them
// would arm a replay with a previous submission's classification.
const PRISTINE = ['canonical_lead_id','claimed_at','settled_at','abort_reason','lead_mode','lead_priority','financial_zone'];
const dirty = PRISTINE.filter(f => norm(row[f]) !== '');
if (dirty.length) { return refuse('READBACK_NOT_PRISTINE', { __dirty_fields: dirty.join(',') }); }
// A freshly preallocated receipt has not been claimed, so it cannot yet carry a correlation id.
// A non-empty one means this row is not a pristine preallocation.
if (norm(row.correlation_id) !== '') { return refuse('READBACK_ALREADY_CLAIMED'); }

// created_at must be PRESENT and parseable. A receipt with no creation time cannot be aged for
// retention and cannot be ordered against anything, and an unparseable one is a row nobody wrote
// through buildPreallocation. Checked, never repaired: substituting a default would hide the
// write that produced it.
const createdAt = row.created_at;
if (typeof createdAt !== 'string' || createdAt.trim() === '') { return refuse('READBACK_CREATED_AT_MISSING'); }
if (!Number.isFinite(Date.parse(createdAt))) { return refuse('READBACK_CREATED_AT_INVALID'); }

// The verdict NAMES the key it verified, so the authority write is bound to THIS issuance
// structurally rather than by trusting the branch it arrived on.
return [{ json: {
  __advance: true,
  __reason: 'PREALLOCATION_CONFIRMED',
  __verified_submission_key: key,
  __rows_seen: rows.length,
  __insert_errored: insertErrored
} }];

// B.2.1-C P7.2 — the fail-closed terminal, reached from EITHER the fault branch or the readback
// verdict.
//
// The turn persists NOTHING to Bot_Sessions, and that is the whole point. It is not a new class
// of harm: Build Delivery Failure Event beside it already discards a proposed session on every
// failed send. planIssuance() is explicit that keeping the OLD cycle current beats advancing to
// a cycle with no receipt behind it — every submit on a half-advanced row is
// PRE_ACTIVATION_BLOCKED, which locks the user out of a cycle that looks current.
//
// Because Save Bot Session does not run, IF Lead Ready downstream of it does not run either, so
// no lead is handed to Intake for a cycle that no authority row names. That suppression is
// deliberate, not a side effect.
//
// THE KEY ITSELF IS NEVER LOGGED. A submission_key is a capability: whoever holds it can claim
// the receipt. Bot_Events is a spreadsheet with wider read access than the Data Table, so this
// row records only whether a key was PRESENT.
//
// F16: Bot_Events is written with autoMapInputData and an EMPTY stored schema, so a stray
// property here would permanently widen the live sheet. The key set below is exactly the one
// Build Bot Event and Build Delivery Failure Event already emit — twelve, no more.
const p = $('Parse Telegram Update').first().json;
const b = $('Build Bot Response').first().json;
const d = b.debug || {};
const gate = $('Issuance Gate').first().json || {};
let v = {};
try { v = $('Issuance Verdict').first().json || {}; } catch (e) { v = {}; }
const reason = String(v.__reason || gate.__fault_reason || 'ISSUANCE_UNCONFIRMED');
return [{ json: {
  event_id: `${p.chat_id}-${Date.now()}`,
  ts: new Date().toISOString(),
  chat_id: String(p.chat_id || ''),
  user_id: String(p.user_id || ''),
  username: String(p.username || ''),
  event_type: p.is_callback ? 'callback_received' : 'message_received',
  state_before: String(d.state_before || ''),
  state_after: String(d.state_before || ''),
  message_text: String(p.message_text || '').slice(0, 500),
  callback_data: String(p.callback_data || ''),
  detail: 'issuance_unconfirmed: ' + reason,
  raw_json: JSON.stringify({
    issuance_action: gate.__issuance_action || '',
    issuance_reason: gate.__issuance_reason || '',
    fault_reason: gate.__fault_reason || '',
    readback_reason: v.__reason || '',
    rows_seen: v.__rows_seen === undefined ? null : v.__rows_seen,
    insert_errored: v.__insert_errored === true,
    dirty_fields: v.__dirty_fields || '',
    proposed_state_discarded: d.state_after || '',
    submission_key_present: String(gate.__submission_key || '') !== ''
